def set_generated_name(apps: Apps, schema_editor: BaseDatabaseSchemaEditor):
    db_alias = schema_editor.connection.alias
    Prompt = apps.get_model("authentik_stages_prompt", "prompt")

    for prompt in Prompt.objects.using(db_alias).all():
        name = prompt.field_key
        stage = prompt.promptstage_set.using(db_alias).order_by("name").first()
        if stage:
            name += "_" + stage.name
        else:
            name += "_" + str(uuid.uuid4())
        prompt.name = name
        prompt.save()



def migrate_placeholder_expressions(apps: Apps, schema_editor: BaseDatabaseSchemaEditor):
    from authentik.stages.prompt.models import CHOICE_FIELDS

    db_alias = schema_editor.connection.alias
    Prompt = apps.get_model("authentik_stages_prompt", "prompt")

    for prompt in Prompt.objects.using(db_alias).all():
        if not prompt.placeholder_expression or prompt.type in CHOICE_FIELDS:
            continue

        prompt.initial_value = prompt.placeholder
        prompt.initial_value_expression = True
        prompt.placeholder = ""
        prompt.placeholder_expression = False
        prompt.save()


def copy_prompt_order_to_field(apps: Apps, schema_editor: BaseDatabaseSchemaEditor):
    """Seed per-stage field order from the prompt's global order, so ordering is
    unchanged on upgrade (rendering previously sorted by Prompt.order)."""
    PromptStageField = apps.get_model("authentik_stages_prompt", "PromptStageField")
    db_alias = schema_editor.connection.alias
    fields = list(PromptStageField.objects.using(db_alias).select_related("prompt"))
    for field in fields:
        field.order = field.prompt.order
    PromptStageField.objects.using(db_alias).bulk_update(fields, ["order"])


